(() => {const texture=new Image();let ready=false;function draw(c,i,x,y,w,h){const sw=texture.width/4,sh=texture.height/3;c.drawImage(texture,i%4*sw,Math.floor(i/4)*sh,sw,sh,x,y,w,h)}window.drawTerrainTile=(c,x,y,seed)=>{if(!ready)return false;const code=((x*73856093)^(y*19349663)^seed)>>>0;const edge=x===1||x===8||y===1||y===6;const variants=edge?[0,1,2,3,4,5,6,7]:[0,1,2,7];draw(c,variants[code%variants.length],-.5,-.5,1,1);return true};window.drawWallTile=(c,x,y,seed)=>{if(!ready)return false;const code=((x*347)^(y*113)^seed)>>>0,i=8+code%4,sw=texture.width/4,sh=texture.height/3,sx=i%4*sw,sy=2*sh;
 c.save();c.translate(x+.5,y+.5);const turn=y===0?0:y===7?Math.PI:x===0?-Math.PI/2:Math.PI/2;c.rotate(turn);
 c.drawImage(texture,sx,sy,sw,sh*.56,-.5,-.5,1,.76);c.drawImage(texture,sx,sy+sh*.56,sw,sh*.44,-.5,.26,1,.24);c.restore();return true};texture.onload=()=>{ready=true;window.gameDebug?.render()};texture.src='assets/terrain-soft.png';})();
